package com.northstarbank.console.domain;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="audit_events") public class AuditEvent{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;public String actor;public String action;public String resourceClass;public Integer recordCount;public String customerRef;public String scope;public String authorizationBasis;@Column(length=4000)public String beforeValue;@Column(length=4000)public String afterValue;public Instant occurredAt=Instant.now();protected AuditEvent(){}public AuditEvent(String actor,String action,String type,int count,String ref,String scope,String basis,String before,String after){this.actor=actor;this.action=action;resourceClass=type;recordCount=count;customerRef=ref;this.scope=scope;authorizationBasis=basis;beforeValue=before;afterValue=after;}}
